use pretty_assertions::assert_eq;
use std::ffi::CStr;
use std::ffi::c_char;
use std::ffi::c_int;
use std::ffi::c_uint;
use std::ffi::c_void;
use std::fs::OpenOptions;
use std::fs::TryLockError;
